head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = ""; // R=접수, H = 이력, N : 신규
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.clickBokRow;

scwin.fr_SecuGrpId = SECUGRP_ID_EF;
scwin.vSYMBL_INPUT_CD;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        MaxTab_01.setSelectedTabIndex(1);
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        scwin.vSYMBL_INPUT_CD = js_market;
        scwin.setComponentSymbl();
        await scwin.recvListSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05316.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_New_onclick
 * @description 「신규등록」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
            txb_ISU_CD.focus();
            return;
        }
        await scwin.openDetailMng(-1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05316.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            await scwin.allListSync();
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            await scwin.bokListSync();
        }
        // jackal_11.05.12
        else if (MaxTab_01.getSelectedTabIndex() === 3) {
            await scwin.bokListTujaSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05316.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.stf.doLogSave("ULDSTF05316.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_List, {fileName: "종목명변경 내역", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            $c.stf.doLogSave("ULDSTF05316.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_Bok_Recv, {fileName: "원부변경 내역", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 3) {
            $c.stf.doLogSave("ULDSTF05316.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_Bok_Recv_Tuja, {fileName: "원부변경 내역", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05316.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05316.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    try {
        let rCnt = '';
        if (nIndex === '1') {
            panel_New.show("");
            rCnt = dts_List.getRowCount();
        } else if (nIndex === '2') {
            panel_New.hide();
            rCnt = dts_Bok_Recv.getRowCount();
        }
        // jackal_11.05.12
        else if (nIndex === '3') {
            panel_New.hide();
            rCnt = dts_Bok_Recv_Tuja.getRowCount();
        }
        $c.stf.fillGridHeaderTotalCnt(rCnt, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05316.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name img_ISU_CD_onclick
 * @description img_ISU_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_CD_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsuCd;
        scwin.fn_SetPar = scwin.setParIsuCd;
        $c.lc.fn_PopFindIsu(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05316.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name grd_Recv_OnClick
 * @description grd_Recv 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Recv_OnClick = async function(row, colid) {
    try {
        txb_ISU_CD.setValue(dts_Recv.getCellData(row, "ISU_CD"));
        txb_ISU_NM.setValue(dts_Recv.getCellData(row, "ISU_KOR_NM"));
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05316.grd_Recv_OnClick" });
    }
};

/**
 * @method
 * @name grd_Recv_OnDblClick
 * @description grd_Recv 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Recv_OnDblClick = function(row, colid) {
    try {
        $c.elw.fn_OpenDetailRecv(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05316.grd_Recv_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_Bok_Recv_OnDblClick
 * @description grd_Bok_Recv 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
