    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05316.grd_Bok_Recv_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_Bok_Recv_Tuja_OnDblClick
 * @description grd_Bok_Recv_Tuja 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
