///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name recvListSync
 * @description recv List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvListSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05316.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ISU_NM_RECV_LIST + "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
    const sbmOptions = {
        id : "sbm_dts_Recv",
        action : "/Listing.do",
        ref : "",
        target : "dts_Recv=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05316.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ISU_NM_HIST_LIST + "&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/Listing.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name bokListSync
 * @description bok List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bokListSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05316.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ETF_BOK_RECV_LIST;
    const sbmOptions = {
        id : "sbm_dts_Bok_Recv",
        action : "/Listing.do",
        ref : "",
        target : "dts_Bok_Recv=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name bokListTujaSync
 * @description bok List Tuja Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bokListTujaSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05316.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_BOK_CHG_TUJA_OUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.lstlst.select.etf.recv.list.bokchglist.tuja.condition";
    const sbmOptions = {
        id : "sbm_dts_Bok_Recv_Tuja",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Bok_Recv_Tuja=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsuCd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description set Par Isu Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsuCd = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        btn_Search.trigger("onclick");
    }
};

/**
 * @method
 * @name allListSync
 * @description all List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.allListSync = async function() {
    await scwin.recvListSync();
    await scwin.listSync();
};

/**
 * @method
 * @name openDetailRecv
 * @description open Detail Recv 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailRecv = async function(row) {
    scwin.vOpenTyp = "R";
    scwin.clickBzProcsNo = ""; // 초기화
    scwin.vAcptNo = dts_Recv.getCellData(row, "ACPT_NO");
    scwin.vIsurCd = dts_Recv.getCellData(row, "ISUR_CD");
    scwin.clickBzProcsNo = dts_Recv.getCellData(row, "BZ_PROCS_NO");
    await scwin.openPopup();
};

/**
 * @method
 * @name openDetailMng
 * @description open Detail Mng 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailMng = async function(row) {
    scwin.vAcptNo = ""; // 초기화
    if (row > 0) {
        // 그리드에서 선택시
        scwin.vOpenTyp = "H";
        scwin.setBzProcsNo(row);
    } else {
        // 신규버튼 선택시
        scwin.vOpenTyp = "N";
        scwin.clickBzProcsNo = ""; // 초기화

    }
    await scwin.openPopup();
};

/**
 * @method
 * @name openDetailBokRecv
 * @description open Detail Bok Recv 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailBokRecv = async function(row) {
    scwin.clickBokRow = row;
    const options = {
        id: "ULDSTF05318",
        title: "원부변경 관리",
        type: "browserPopup",
        width: 665 + 25,
        height: 390 + 50,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05318.gfm", options);
};

/**
 * @method
 * @name openDetailBokRecvTuja
 * @description open Detail Bok Recv Tuja 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
