        id: "ULDSTF05319",
        title: "원부변경 관리",
        type: "browserPopup",
        width: 665 + 25,
        height: 390 + 50,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05319.gfm", options);
};

